def crear_metricas_base(apps, schema_editor):
    Metrica = apps.get_model("dashboard", "Metrica")
    Proyecto = apps.get_model("dashboard", "Proyecto")
    base = [
        Metrica.objects.update_or_create(
            nombre=datos["nombre"], defaults={**datos, "es_base": True}
        )[0]
        for datos in METRICAS_BASE
    ]
    # Los proyectos que ya existían también reciben las métricas base.
    for proyecto in Proyecto.objects.all():
        proyecto.metricas.add(*base)


